param([string]$Configuration="Release",[string]$BuildDir="build",[string]$JuceDir="",[switch]$BootstrapJuce,[switch]$SkipBuild,[switch]$SkipInstaller,[string]$InnoSetupPath="",[string]$AppVersion="")
$ErrorActionPreference="Stop";$r=Split-Path -Parent $PSCommandPath;$slug=Split-Path -Leaf $r;$x=Get-Content (Join-Path $r "CMakeLists.txt") -Raw;$m=[regex]::Match($x,'project\(([^\s\)]+)\s+VERSION\s+([0-9.]+)');$p=[regex]::Match($x,'PRODUCT_NAME\s+"([^"]+)"');$t=$m.Groups[1].Value;$v=if($AppVersion){$AppVersion}else{$m.Groups[2].Value};$n=$p.Groups[1].Value;if(!$SkipBuild){& (Join-Path $r "_build_all.ps1") -Configuration $Configuration -BuildDir $BuildDir -JuceDir $JuceDir -BootstrapJuce:$BootstrapJuce};$b=Join-Path $r "$BuildDir\${t}_artefacts\$Configuration";$e=Get-ChildItem (Join-Path $b "Standalone") -File -Filter *.exe|Select-Object -First 1;$z=Get-ChildItem (Join-Path $b "VST3") -Directory -Filter *.vst3|Select-Object -First 1;$rel=Join-Path $r "release";$s=Join-Path $rel "staging";if(Test-Path $s){Remove-Item $s -Recurse -Force};New-Item -ItemType Directory (Join-Path $s "Standalone"),(Join-Path $s "VST3") -Force|Out-Null;Copy-Item $e.FullName (Join-Path $s "Standalone");Copy-Item $z.FullName (Join-Path $s "VST3") -Recurse;$pr=Join-Path $r "Presets";Copy-Item $pr (Join-Path $s "Standalone\Presets") -Recurse;Copy-Item $pr (Join-Path (Join-Path $s "VST3\$($z.Name)") "Presets") -Recurse;New-Item -ItemType Directory $rel -Force|Out-Null;Compress-Archive -Path "$s\*" -DestinationPath (Join-Path $rel "${slug}_${v}_Windows_x64_Portable.zip") -Force;if(!$SkipInstaller){$c=@($InnoSetupPath,"C:\Program Files (x86)\Inno Setup 6\ISCC.exe","C:\Program Files\Inno Setup 6\ISCC.exe","D:\InnoSetup6\ISCC.exe")|Where-Object{$_-and(Test-Path $_)};$i=$c|Select-Object -First 1;if(!$i){throw "Inno Setup 6 not found"};&$i "/DAppName=$n" "/DAppVersion=$v" "/DRepoSlug=$slug" "/DStandaloneSource=$($e.FullName)" "/DStandaloneExeName=$($e.Name)" "/DVst3Source=$($z.FullName)" "/DVst3DirName=$($z.Name)" "/DPresetsSource=$pr" "/DOutputDir=$rel" "/DOutputBaseFilename=${slug}_${v}_Windows_x64_Setup" (Join-Path $r "installer\MusiqueFX.iss")}}
